class Paper < ApplicationRecord
  # Generated by PostgreSQL; ActiveRecord must never write it.
  self.ignored_columns += ["search_vector"]

  has_many :authorships
  has_many :professors, -> { order(:name) }, through: :authorships
  has_one :paper_embedding

  SEARCH_LIMIT = 50
  COUNT_CAP = 1000
  SEMANTIC_LIMIT = 200 # semantic and hybrid modes rank the closest 200 papers
  RRF_K = 60           # Reciprocal Rank Fusion constant (Cormack et al. 2009)

  # Versions of one work (see collapse_versions). Published versions are kept over chapters and preprints.
  VERSION_PREFERENCE = { "conference-paper" => 0, "article" => 0, "book-chapter" => 1, "preprint" => 2 }.freeze
  VERSION_MIN_TITLE_WORDS = 4 # shorter titles ("Graph Neural Networks") are too generic to match on
  VERSION_MAX_YEAR_GAP = 3    # a preprint can appear a few years before its published version
  Versions = Struct.new(:ids, :hidden) # hidden: kept id => [[paper_type, year], ...] of the copies left out

  # Sort choices for search results (key => label). Anything else means "relevance".
  # Author-based sorts use a paper's alphabetically first professor / university.
  SORTS = {
    "relevance" => "Relevance",
    "year_desc" => "Year (newest first)",
    "year_asc" => "Year (oldest first)",
    "university" => "University",
    "professor" => "Professor",
    "venue" => "Venue"
  }.freeze

  FIRST_PROFESSOR = "(SELECT MIN(pr.name) FROM authorships au JOIN professors pr ON pr.id = au.professor_id WHERE au.paper_id = papers.id)".freeze
  FIRST_UNIVERSITY = "(SELECT MIN(un.name) FROM authorships au JOIN professors pr ON pr.id = au.professor_id JOIN universities un ON un.id = pr.university_id WHERE au.paper_id = papers.id)".freeze

  def self.sort_order(sort)
    case sort
    when "year_desc" then "papers.year DESC NULLS LAST"
    when "year_asc" then "papers.year ASC NULLS LAST"
    when "university" then "#{FIRST_UNIVERSITY} ASC NULLS LAST"
    when "professor" then "#{FIRST_PROFESSOR} ASC NULLS LAST"
    when "venue" then "lower(papers.venue) ASC NULLS LAST"
    end
  end

  # Papers whose title, keywords, primary topic or abstract match the query.
  def self.matching(query)
    where("papers.search_vector @@ #{tsquery(query)}")
  end

  # One page (SEARCH_LIMIT papers) of matches, best first, with authors loaded.
  def self.search(query, page: 1, sort: "relevance")
    order = [sort_order(sort), "ts_rank(papers.search_vector, #{tsquery(query)}) DESC", "papers.id"].compact.join(", ")
    matching(query)
      .order(Arel.sql(order))
      .limit(SEARCH_LIMIT)
      .offset((page - 1) * SEARCH_LIMIT)
      .includes(professors: :university)
  end

  # Paper ids closest in meaning to the query, nearest first (cosine distance on Voyage embeddings).
  def self.semantic_ids(query)
    vector = "[#{query_embedding(query).map { |x| Float(x) }.join(',')}]"
    transaction do
      # HNSW returns at most ef_search rows; raise it so all SEMANTIC_LIMIT neighbours come back.
      connection.execute("SET LOCAL hnsw.ef_search = #{SEMANTIC_LIMIT * 2}")
      connection.select_values(sanitize_sql_array([<<~SQL, vector, SEMANTIC_LIMIT])).map(&:to_i)
        SELECT paper_id FROM paper_embeddings ORDER BY embedding <=> ?::vector LIMIT ?
      SQL
    end
  end

  # Keyword and semantic rankings merged with Reciprocal Rank Fusion: score = sum of 1 / (RRF_K + rank).
  def self.hybrid_ids(query)
    keyword = matching(query).order(Arel.sql("ts_rank(papers.search_vector, #{tsquery(query)}) DESC, papers.id"))
                             .limit(SEMANTIC_LIMIT).pluck(:id)
    scores = Hash.new(0.0)
    [keyword, semantic_ids(query)].each do |ids|
      ids.each_with_index { |id, i| scores[id] += 1.0 / (RRF_K + i + 1) }
    end
    scores.sort_by { |id, score| [-score, id] }.first(SEMANTIC_LIMIT).map(&:first)
  end

  # Ranked ids with each work listed once. Some works are stored more than once (a preprint and
  # its published version, or journal and conference records of one paper), and their embeddings
  # are nearly identical, so both copies land next to each other in meaning results.
  #
  # Two papers are versions of one work when they have the same title (ignoring case, accents and
  # punctuation; at least VERSION_MIN_TITLE_WORDS words), share a roster author, and were published
  # at most VERSION_MAX_YEAR_GAP years apart. One copy per work is kept: a published version over a
  # book chapter over a preprint, then the higher-ranked. It takes the best rank any copy had.
  def self.collapse_versions(ids)
    return Versions.new(ids, {}) if ids.size < 2

    papers = where(id: ids).pluck(:id, :title, :year, :paper_type).to_h { |id, title, year, type| [id, [version_key(title), year, type]] }
    ids = ids.select { |id| papers.key?(id) } # ranked_page would drop a missing paper anyway
    rank = ids.each_with_index.to_h
    authors = Authorship.where(paper_id: ids).pluck(:paper_id, :professor_id)
                        .group_by(&:first).transform_values { |rows| rows.map(&:last).to_set }
    work = ids.to_h { |id| [id, id] } # union-find: id => representative

    find = ->(id) { work[id] == id ? id : (work[id] = find.(work[id])) }
    papers.group_by { |_, (key, _, _)| key }.each do |key, same_title|
      next if key.split.size < VERSION_MIN_TITLE_WORDS

      same_title.map(&:first).combination(2).each do |a, b|
        next if (papers[a][1] - papers[b][1]).abs > VERSION_MAX_YEAR_GAP
        next unless authors.fetch(a, Set.new).intersect?(authors.fetch(b, Set.new))

        work[find.(a)] = find.(b)
      end
    end

    copies = ids.group_by { |id| find.(id) }.values
    keep = copies.to_h { |group| [group, group.min_by { |id| [VERSION_PREFERENCE.fetch(papers[id][2], 3), rank[id]] }] }
    hidden = {}
    kept = copies.sort_by { |group| group.map { |id| rank[id] }.min }.map do |group|
      kept_id = keep[group]
      others = (group - [kept_id]).sort_by { |id| rank[id] }
      hidden[kept_id] = others.map { |id| [papers[id][2], papers[id][1]] } if others.any?
      kept_id
    end
    Versions.new(kept, hidden)
  end

  # A title reduced to lowercase letters and digits separated by single spaces ("é" becomes "e").
  def self.version_key(title)
    title.to_s.scrub.unicode_normalize(:nfkd).gsub(/\p{Mn}/, "").downcase.gsub(/[^a-z0-9]+/, " ").strip
  end

  # One page of the given ranked ids, in that order unless a sort is chosen, with authors loaded.
  def self.ranked_page(ids, page: 1, sort: "relevance")
    return none if ids.empty?

    position = sanitize_sql_array(["array_position(ARRAY[?]::bigint[], papers.id)", ids])
    where(id: ids)
      .order(Arel.sql([sort_order(sort), position].compact.join(", ")))
      .limit(SEARCH_LIMIT)
      .offset((page - 1) * SEARCH_LIMIT)
      .includes(professors: :university)
  end

  # The query's Voyage embedding, cached so repeating a search costs no API call.
  # Searches that differ only in case or spacing share one embedding and one cache entry
  # (see normalize_query). No retries here: a slow Voyage falls back to keyword search well
  # inside Heroku's 30 s request limit.
  def self.query_embedding(query)
    text = normalize_query(query)
    Rails.cache.fetch(["query-embedding", VoyageClient::MODEL, text], expires_in: 1.week) do
      VoyageClient.embed([text], input_type: "query", timeout: 3).first
    end
  end

  # The text embedded for a search: Unicode compatibility forms unified (NFKC, so full-width
  # letters and ligatures match their plain forms), lowercase, single spaces, no outer spaces.
  def self.normalize_query(query) = query.to_s.scrub.unicode_normalize(:nfkc).downcase.squish

  def self.tsquery(query) = sanitize_sql_array(["websearch_to_tsquery('english', ?)", query])
  private_class_method :tsquery
end
